import React, { useState } from 'react';
import {
  Box,
  Typography,
  TextField,
  Button,
  IconButton,
  InputAdornment,
  Paper,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Grid,
  Snackbar,
  Alert,
  CircularProgress,
  FormControl,
  FormHelperText
} from '@mui/material';
import { Visibility, VisibilityOff } from '@mui/icons-material';
import { useAuth } from './AuthContext';

const ProfileTab = () => {
  const { user } = useAuth();
  const [newUsername, setNewUsername] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [oldPassword, setOldPassword] = useState('');
  const [showNewPassword, setShowNewPassword] = useState(false);
  const [showOldPassword, setShowOldPassword] = useState(false);
  const [isUpdating, setIsUpdating] = useState(false);
  const [snackbar, setSnackbar] = useState({
    open: false,
    message: '',
    severity: 'success'
  });

  const [openConfirmUsername, setOpenConfirmUsername] = useState(false);
  const [openConfirmPassword, setOpenConfirmPassword] = useState(false);
  const [errors, setErrors] = useState({
    oldPassword: '',
    newPassword: ''
  });

  const toggleNewPasswordVisibility = () => {
    setShowNewPassword((prev) => !prev);
  };

  const toggleOldPasswordVisibility = () => {
    setShowOldPassword((prev) => !prev);
  };

  const handleUsernameChange = (e) => {
    setNewUsername(e.target.value);
  };

  const handleNewPasswordChange = (e) => {
    setNewPassword(e.target.value);
    // Clear any existing error
    if (errors.newPassword) {
      setErrors({
        ...errors,
        newPassword: ''
      });
    }
  };

  const handleOldPasswordChange = (e) => {
    setOldPassword(e.target.value);
    // Clear any existing error
    if (errors.oldPassword) {
      setErrors({
        ...errors,
        oldPassword: ''
      });
    }
  };

  const handleOpenUsernameDialog = () => {
    if (!newUsername) {
      showSnackbarMessage('Please enter a new username', 'error');
      return;
    }

    if (newUsername === user.username) {
      showSnackbarMessage('New username must be different from current username', 'error');
      return;
    }

    setOpenConfirmUsername(true);
  };

  const handleOpenPasswordDialog = () => {
    let hasErrors = false;
    const newErrors = { ...errors };

    if (!oldPassword) {
      newErrors.oldPassword = 'Please enter your current password';
      hasErrors = true;
    }

    if (!newPassword) {
      newErrors.newPassword = 'Please enter a new password';
      hasErrors = true;
    } else if (newPassword === oldPassword) {
      newErrors.newPassword = 'New password must be different from current password';
      hasErrors = true;
    }

    if (hasErrors) {
      setErrors(newErrors);
      return;
    }

    setOpenConfirmPassword(true);
  };

  const showSnackbarMessage = (message, severity = 'success') => {
    setSnackbar({
      open: true,
      message,
      severity
    });
  };

  const confirmUsernameUpdate = async () => {
    if (!user || !user.workerID) {
      showSnackbarMessage('User information is missing', 'error');
      return;
    }

    setIsUpdating(true);

    try {
      const response = await fetch(`http://localhost:8080/worker/update`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          ...user, 
          username: newUsername 
        }),
      });

      if (response.ok) {
        // Update local storage with the new username
        const updatedUser = { ...user, username: newUsername };
        localStorage.setItem('user', JSON.stringify(updatedUser));
        localStorage.setItem('username', newUsername);

        // Update user data in auth context
        // This would typically update the user in the auth context, but would require adding
        // an updateUser method to the auth context

        setNewUsername('');
        showSnackbarMessage('Username updated successfully!');
      } else {
        showSnackbarMessage('Failed to update username', 'error');
      }
    } catch (err) {
      console.error('Error updating username:', err);
      showSnackbarMessage('Error updating username: ' + err.message, 'error');
    } finally {
      setIsUpdating(false);
      setOpenConfirmUsername(false);
    }
  };

  const confirmPasswordUpdate = async () => {
    if (!user || !user.workerID) {
      showSnackbarMessage('User information is missing', 'error');
      return;
    }

    setIsUpdating(true);

    try {
      // First, verify old password
      const verifyResponse = await fetch('http://localhost:8080/worker/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          username: user.username, 
          password: oldPassword 
        }),
      });

      if (!verifyResponse.ok) {
        setErrors({
          ...errors,
          oldPassword: 'Current password is incorrect'
        });
        setIsUpdating(false);
        setOpenConfirmPassword(false);
        return;
      }

      // Update with new password
      const response = await fetch(`http://localhost:8080/worker/update`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          ...user, 
          password: newPassword 
        }),
      });

      if (response.ok) {
        setNewPassword('');
        setOldPassword('');
        showSnackbarMessage('Password updated successfully!');
      } else {
        showSnackbarMessage('Failed to update password', 'error');
      }
    } catch (err) {
      console.error('Error updating password:', err);
      showSnackbarMessage('Error updating password: ' + err.message, 'error');
    } finally {
      setIsUpdating(false);
      setOpenConfirmPassword(false);
    }
  };

  const handleCloseSnackbar = () => {
    setSnackbar({
      ...snackbar,
      open: false
    });
  };

  const handleCloseUsernameDialog = () => {
    setOpenConfirmUsername(false);
  };

  const handleClosePasswordDialog = () => {
    setOpenConfirmPassword(false);
  };

  if (!user) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '70vh' }}>
        <CircularProgress />
      </Box>
    );
  }

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" sx={{ fontWeight: 'bold', textAlign: 'center', mb: 4 }}>
        {user.firstName}'s Profile
      </Typography>

      <Paper elevation={3} sx={{ p: 4, maxWidth: 600, mx: 'auto' }}>
        <Grid container spacing={3}>
          <Grid item xs={12}>
            <Typography variant="h5" sx={{ mb: 2, textAlign: 'center' }}>
              {user.firstName} {user.lastName}
            </Typography>
            <Typography variant="subtitle1" sx={{ mb: 2, textAlign: 'center', color: 'text.secondary' }}>
              {user.isAdmin ? 'Administrator' : 'Inspector'}
            </Typography>
          </Grid>

          {/* Username Section */}
          <Grid item xs={12}>
            <Typography variant="h6">Username</Typography>
            <Typography variant="body1" sx={{ mb: 2 }}>
              Current: <strong>{user.username}</strong>
            </Typography>

            <FormControl fullWidth margin="normal">
              <TextField 
                label="New Username" 
                value={newUsername}
                onChange={handleUsernameChange}
                variant="outlined"
                fullWidth
              />
            </FormControl>

            <Box sx={{ display: 'flex', justifyContent: 'flex-end', mt: 2 }}>
              <Button
                variant="contained"
                onClick={handleOpenUsernameDialog}
                disabled={!newUsername || isUpdating}
              >
                Update Username
              </Button>
            </Box>
          </Grid>

          {/* Password Section */}
          <Grid item xs={12} sx={{ mt: 3 }}>
            <Typography variant="h6">Password</Typography>
            <Typography variant="body1" sx={{ mb: 2 }}>
              Change your current password
            </Typography>

            <FormControl fullWidth margin="normal" error={!!errors.oldPassword}>
              <TextField 
                label="Current Password" 
                type={showOldPassword ? 'text' : 'password'}
                value={oldPassword}
                onChange={handleOldPasswordChange}
                variant="outlined"
                fullWidth
                error={!!errors.oldPassword}
                InputProps={{
                  endAdornment: (
                    <InputAdornment position="end">
                      <IconButton onClick={toggleOldPasswordVisibility}>
                        {showOldPassword ? <VisibilityOff /> : <Visibility />}
                      </IconButton>
                    </InputAdornment>
                  ),
                }}
              />
              {errors.oldPassword && (
                <FormHelperText error>{errors.oldPassword}</FormHelperText>
              )}
            </FormControl>

            <FormControl fullWidth margin="normal" error={!!errors.newPassword}>
              <TextField 
                label="New Password" 
                type={showNewPassword ? 'text' : 'password'}
                value={newPassword}
                onChange={handleNewPasswordChange}
                variant="outlined"
                fullWidth
                error={!!errors.newPassword}
                InputProps={{
                  endAdornment: (
                    <InputAdornment position="end">
                      <IconButton onClick={toggleNewPasswordVisibility}>
                        {showNewPassword ? <VisibilityOff /> : <Visibility />}
                      </IconButton>
                    </InputAdornment>
                  ),
                }}
              />
              {errors.newPassword && (
                <FormHelperText error>{errors.newPassword}</FormHelperText>
              )}
            </FormControl>

            <Box sx={{ display: 'flex', justifyContent: 'flex-end', mt: 2 }}>
              <Button
                variant="contained"
                onClick={handleOpenPasswordDialog}
                disabled={!newPassword || !oldPassword || isUpdating}
              >
                Update Password
              </Button>
            </Box>
          </Grid>
        </Grid>
      </Paper>

      {/* Username Confirmation Dialog */}
      <Dialog open={openConfirmUsername} onClose={handleCloseUsernameDialog}>
        <DialogTitle>Confirm Username Change</DialogTitle>
        <DialogContent>
          <Typography>
            Are you sure you want to change your username to <strong>{newUsername}</strong>?
            This action cannot be undone.
          </Typography>
        </DialogContent>
        <DialogActions>
          <Button 
            onClick={handleCloseUsernameDialog} 
            sx={{ color: 'blue', textDecoration: 'underline' }}
          >
            Cancel
          </Button>
          <Button
            onClick={confirmUsernameUpdate}
            variant="contained"
            disabled={isUpdating}
          >
            {isUpdating ? <CircularProgress size={24} /> : 'Yes'}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Password Confirmation Dialog */}
      <Dialog open={openConfirmPassword} onClose={handleClosePasswordDialog}>
        <DialogTitle>Confirm Password Change</DialogTitle>
        <DialogContent>
          <Typography>
            Are you sure you want to change your password?
            This action cannot be undone.
          </Typography>
        </DialogContent>
        <DialogActions>
          <Button 
            onClick={handleClosePasswordDialog} 
            sx={{ color: 'blue', textDecoration: 'underline' }}
          >
            Cancel
          </Button>
          <Button
            onClick={confirmPasswordUpdate}
            variant="contained"
            disabled={isUpdating}
          >
            {isUpdating ? <CircularProgress size={24} /> : 'Yes'}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Snackbar for notifications */}
      <Snackbar
        open={snackbar.open}
        autoHideDuration={6000}
        onClose={handleCloseSnackbar}
        anchorOrigin={{ vertical: 'top', horizontal: 'center' }}
      >
        <Alert 
          onClose={handleCloseSnackbar} 
          severity={snackbar.severity} 
          sx={{ width: '100%' }}
        >
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Box>
  );
};

export default ProfileTab;
